|Variable | Symbol | Wert |
|:-------:|:------:|:-----:|
|Wellenlänge des Photons| λ | 600 nm|
|Lichtgeschwindigkeit | c | 299.792.458 m/s |
|Plancksche Konstante | h | ? |
[C#-Code]
double wavelength = 600 * Math.Pow(10,-9); //nm in Meter umrechnen
double speedOfLight = 299792458;
double energy = (6.62607004 * Math.Pow(10,-34) * speedOfLight) / Wellenlänge; //Energie mithilfe der Planckschen Konstante (h) und der Lichtgeschwindigkeit berechnen
double h = energy / speedOfLight;
Console.WriteLine("Der Wert der Planckschen Konstante (h) lautet: " + h.ToString() + " J s");
Console.WriteLine("Die Energie eines Photons mit einer Wellenlänge von 600 nm lautet: " + energy.ToString() + " J");

